export const GLOSSARY_SHARD = Object.freeze({"tokenomics":{"slug":"tokenomics","cat":"basics","en":"Tokenomics","contentLocale":"ko","term":"토크노믹스(Tokenomics)","aka":["토큰 이코노믹스","Tokenomics","토큰 경제"],"short":"토크노믹스는 토큰의 총발행량, 배분 비율, 언락 일정, 사용처, 소각과 인플레이션 규칙 등 토큰의 공급과 수요를 결정하는 경제 구조 전체를 말합니다.","body":["토크노믹스를 볼 때 가장 먼저 확인하는 것은 공급입니다. 최대 공급량이 있는지, 현재 유통 비율은 얼마인지, 팀·투자자·커뮤니티·생태계 기금에 몇 퍼센트씩 배분됐는지, 언제 얼마나 풀리는지가 핵심입니다.",["다음은 수요입니다. 토큰이 수수료 지불, ",["스테이킹","staking"],", 거버넌스 투표, 담보 등 실제로 쓰이는 곳이 있는지 봐야 합니다. 쓰임새 없이 보상으로만 계속 발행되는 토큰은 시간이 지날수록 매도 압력이 커질 수 있습니다."],["소각, 바이백, 스테이킹 보상률 같은 장치도 토크노믹스의 일부입니다. 다만 설명 자료에 적힌 내용과 실제 ",["컨트랙트","smart-contract"]," 동작이 다를 수 있으므로, 공식 문서와 온체인 데이터를 함께 확인하는 것이 좋습니다."]],"example":["총공급량 10억 개인 토큰이 팀 20%, 투자자 15%, 커뮤니티 보상 40%, 생태계 기금 25%로 배분되었다고 가정해 보겠습니다. 팀과 투자자 물량 3억 5,000만 개가 1년 잠금 후 24개월 동안 매달 같은 양씩 풀린다면 한 달에 약 1,458만 개가 새로 시장에 나옵니다. 현재 ",["유통량","circulating-supply"],"이 1억 개라면 첫 언락 달에만 유통량이 약 15% 늘어나는 셈입니다."],"mistakes":["토큰 배분표에서 팀과 투자자 비율만 보고 언락 일정은 확인하지 않습니다.","소각 계획이 있다는 사실만으로 공급이 줄어든다고 단정합니다.","높은 스테이킹 보상률이 결국 새 토큰 발행으로 지급된다는 점을 놓칩니다."],"faq":[{"q":"좋은 토크노믹스의 기준은 무엇인가요?","a":"정답은 없지만, 공급 일정이 투명하고 내부자 물량이 과도하지 않으며 토큰의 실제 쓰임새가 분명한지를 주로 봅니다. 프로젝트 성격에 따라 적절한 구조가 다릅니다."},{"q":"토크노믹스 정보는 어디서 확인하나요?","a":"프로젝트의 공식 문서나 백서, 토큰 배분표, 그리고 언락 일정을 정리한 데이터 사이트에서 확인할 수 있습니다. 가능하면 온체인 지갑 데이터와 함께 비교하는 것이 좋습니다."}],"title":"토크노믹스란? 뜻과 확인해야 할 항목","description":"토크노믹스의 뜻과 공급·배분·언락·사용처·소각 등 확인해야 할 핵심 항목을 배분표 계산 예시로 정리합니다.","related":[["circulating-supply","유통량(Circulating Supply)","유통량은 현재 시장에서 실제로 거래될 수 있는 코인의 수량으로, 잠겨 있거나 아직 발행되지 않은 물량은 제외합니다."],["token-unlock","토큰 언락(Token Unlock)","토큰 언락은 팀, 투자자, 생태계 기금 등에게 배분된 뒤 잠겨 있던 토큰이 정해진 일정에 따라 풀려 거래 가능한 상태가 되는 것입니다."],["fully-diluted-valuation","완전 희석 가치(FDV)","완전 희석 가치(FDV)는 코인의 현재 가격에 앞으로 발행될 물량까지 포함한 최대 또는 총 공급량을 곱한 값으로, 모든 토큰이 풀렸을 때의 평가 규모를 보여 줍니다."],["token-burn","토큰 소각(Token Burn)","토큰 소각은 누구도 꺼낼 수 없는 주소로 토큰을 보내거나 컨트랙트에서 제거해 공급량을 영구적으로 줄이는 것입니다."],["governance-token","거버넌스 토큰(Governance Token)","거버넌스 토큰은 보유량에 비례해 프로토콜이나 DAO의 주요 결정에 투표할 권리를 주는 토큰입니다."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"order-book":{"slug":"order-book","cat":"trading","en":"Order book","contentLocale":"ko","term":"호가창(Order Book)","aka":["오더북","호가","Order Book"],"short":"호가창은 거래소에 걸려 있는 매수 주문과 매도 주문을 가격별로 정리해 보여 주는 목록으로, 시장의 대기 물량과 유동성을 한눈에 볼 수 있게 해 줍니다.","body":[["호가창은 보통 매도 호가(빨간색 또는 위쪽)와 매수 호가(초록색 또는 아래쪽)로 나뉩니다. 가장 낮은 매도 가격과 가장 높은 매수 가격 사이의 차이가 ",["스프레드","bid-ask-spread"],"이며, 각 가격대에 걸린 수량을 보면 얼마나 많은 물량이 대기 중인지 알 수 있습니다. 국내 ",["거래소","centralized-exchange"],"는 색상이 반대인 경우도 있습니다."],[["지정가 주문","limit-order"],"은 호가창에 올라가 대기하며 ",["유동성","liquidity"],"을 공급하고, ",["시장가 주문","market-order"],"은 호가창의 물량을 즉시 소진하며 체결됩니다. 호가가 얇은 코인에서는 큰 시장가 주문이 여러 가격대를 연속으로 먹어 치워 평균 체결가가 크게 불리해질 수 있습니다."],"호가창의 대량 주문은 실제 체결 의도 없이 걸었다 취소하는 경우도 있어 그대로 믿기 어렵습니다. 호가 깊이, 스프레드, 최근 체결 내역을 함께 보는 것이 좋습니다."],"example":"어떤 코인의 매도 호가가 1.000달러에 2,000개, 1.005달러에 3,000개, 1.010달러에 5,000개 있다고 가정해 보겠습니다. 시장가로 6,000개를 사면 2,000개는 1.000달러, 3,000개는 1.005달러, 남은 1,000개는 1.010달러에 체결됩니다. 총 비용은 6,025달러이고 평균 체결가는 약 1.0042달러입니다. 최우선 호가 1.000달러보다 약 0.42% 비싸게 산 셈입니다.","mistakes":["최우선 호가만 보고 큰 금액 전체가 그 가격에 체결될 것이라 생각합니다.","호가창의 대량 주문을 그대로 지지선이나 저항선으로 믿습니다.","거래소마다 매수·매도 색상이 다르다는 점을 모르고 호가를 반대로 읽습니다."],"faq":[{"q":"호가창에서 빨간색과 초록색은 무엇인가요?","a":"해외 거래소는 대체로 빨간색이 매도, 초록색이 매수 호가입니다. 국내 거래소는 상승을 빨간색, 하락을 파란색으로 표시하는 등 색 체계가 다를 수 있어 라벨을 확인해야 합니다."},{"q":"호가가 얇다는 것은 무슨 뜻인가요?","a":"각 가격대에 걸린 주문 수량이 적다는 뜻입니다. 이런 시장에서는 작은 주문에도 가격이 크게 움직이고 슬리피지가 커집니다."}],"title":"호가창(오더북)이란? 보는 법과 뜻","description":"호가창(오더북)의 뜻과 읽는 법, 매수·매도 호가와 스프레드, 시장가 주문이 여러 호가를 체결하는 원리를 예시로 설명합니다.","related":[["bid-ask-spread","스프레드(Bid-Ask Spread)","스프레드는 호가창에서 가장 높은 매수 호가(bid)와 가장 낮은 매도 호가(ask) 사이의 가격 차이로, 즉시 사고팔 때 부담하는 숨은 거래 비용입니다."],["limit-order","지정가 주문(Limit Order)","지정가 주문은 사거나 팔 가격을 직접 정해 두고, 시장 가격이 그 가격이나 더 유리한 가격에 도달했을 때만 체결되는 주문입니다."],["market-order","시장가 주문(Market Order)","시장가 주문은 가격을 지정하지 않고 현재 호가창에 있는 가장 유리한 가격부터 즉시 체결하는 주문으로, 빠른 체결을 대가로 가격을 보장받지 못합니다."],["liquidity","유동성(Liquidity)","유동성은 원하는 수량의 자산을 가격을 크게 움직이지 않고 빠르게 사고팔 수 있는 정도를 뜻하며, 호가창의 두께와 스프레드로 확인할 수 있습니다."],["slippage","슬리피지(Slippage)","슬리피지는 주문할 때 예상한 가격과 실제로 체결된 평균 가격의 차이로, 호가가 얇거나 가격이 빠르게 움직일 때 커집니다."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"화면에 보이는 가격이 왜 내 실제 체결 가격이 아닐까요?"},"coin":null,"tool":null,"cta":true},"liquidity":{"slug":"liquidity","cat":"trading","en":"Liquidity","contentLocale":"ko","term":"유동성(Liquidity)","aka":["liquidity","시장 유동성"],"short":"유동성은 원하는 수량의 자산을 가격을 크게 움직이지 않고 빠르게 사고팔 수 있는 정도를 뜻하며, 호가창의 두께와 스프레드로 확인할 수 있습니다.","body":[["유동성이 높은 시장에서는 매수·매도 호가 사이 간격인 ",["스프레드","bid-ask-spread"],"가 좁고, 각 가격대에 쌓인 주문 물량이 많습니다. 그래서 큰 주문을 넣어도 체결 가격이 예상과 크게 다르지 않습니다."],["반대로 유동성이 낮은 ",["알트코인","altcoin"],"이나 ",["신규 상장","token-listing"]," 코인은 호가가 얇아 ",["시장가 주문","market-order"]," 하나에도 가격이 여러 단계 밀립니다. 이때 생기는 예상가와 실제 체결가의 차이를 ",["슬리피지","slippage"],"라고 합니다."],["같은 코인이라도 ",["거래소","centralized-exchange"],"마다 유동성이 다릅니다. 선물 시장은 현물보다 유동성이 두꺼운 경우가 많고, 탈중앙화 거래소에서는 호가창 대신 유동성 풀의 규모가 유동성을 결정합니다."]],"example":"어떤 코인의 매도 호가가 1.00달러에 2,000개, 1.02달러에 3,000개, 1.05달러에 5,000개 쌓여 있다고 가정해 보겠습니다. 시장가로 6,000개를 사면 2,000개는 1.00달러, 3,000개는 1.02달러, 나머지 1,000개는 1.05달러에 체결됩니다. 총 비용은 2,000 + 3,060 + 1,050 = 6,110달러로 평균 단가가 약 1.018달러가 되어, 처음 본 가격보다 약 1.8% 비싸게 산 셈입니다.","mistakes":["차트 가격만 보고 주문해 얇은 호가에서 큰 슬리피지를 맞습니다.","거래량이 많으면 유동성도 충분하다고 단정하지만, 호가창의 실제 물량은 따로 확인해야 합니다.","유동성이 적은 시간대나 급변 구간에 시장가 손절을 걸어 예상보다 훨씬 나쁜 가격에 체결됩니다."],"faq":[{"q":"유동성이 높은지 어떻게 확인하나요?","a":"스프레드가 좁은지, 현재가 근처 호가에 물량이 충분히 쌓여 있는지를 보면 됩니다. 일부 거래소는 일정 비율 가격 범위 안의 호가 깊이를 따로 보여 줍니다."},{"q":"유동성이 낮으면 왜 위험한가요?","a":"원하는 가격에 사고팔기 어렵고, 손절할 때도 가격이 크게 밀려 손실이 커질 수 있습니다. 소수의 큰 주문만으로 가격이 쉽게 움직이기도 합니다."}],"title":"유동성이란? 코인 거래에서 유동성의 의미","description":"코인 시장의 유동성이 무엇인지, 호가창과 스프레드로 확인하는 법, 유동성이 낮을 때 생기는 슬리피지를 설명합니다.","related":[["order-book","호가창(Order Book)","호가창은 거래소에 걸려 있는 매수 주문과 매도 주문을 가격별로 정리해 보여 주는 목록으로, 시장의 대기 물량과 유동성을 한눈에 볼 수 있게 해 줍니다."],["slippage","슬리피지(Slippage)","슬리피지는 주문할 때 예상한 가격과 실제로 체결된 평균 가격의 차이로, 호가가 얇거나 가격이 빠르게 움직일 때 커집니다."],["bid-ask-spread","스프레드(Bid-Ask Spread)","스프레드는 호가창에서 가장 높은 매수 호가(bid)와 가장 낮은 매도 호가(ask) 사이의 가격 차이로, 즉시 사고팔 때 부담하는 숨은 거래 비용입니다."],["liquidity-pool","유동성 풀(Liquidity Pool)","유동성 풀은 DEX에서 거래가 가능하도록 두 가지 이상의 토큰을 스마트 컨트랙트에 함께 예치해 둔 자금 저장소로, 공급자는 거래 수수료를 나눠 받습니다."],["market-maker","마켓메이커(Market Maker)","마켓메이커는 매수 호가와 매도 호가를 동시에 꾸준히 걸어 두어 다른 사람이 언제든 거래할 수 있도록 유동성을 공급하는 참여자입니다."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"화면에 보이는 가격이 왜 내 실제 체결 가격이 아닐까요?"},"coin":null,"tool":null,"cta":false},"isolated-margin":{"slug":"isolated-margin","cat":"derivatives","en":"Isolated margin","contentLocale":"ko","term":"격리 마진(Isolated Margin)","aka":["격리","isolated margin","격리 모드"],"short":"격리 마진은 포지션마다 증거금을 따로 배정해, 그 포지션이 청산되더라도 배정한 증거금만 잃고 계좌의 나머지 잔고는 영향을 받지 않는 마진 방식입니다.","body":[["격리 마진에서 포지션을 열면 그 포지션에 넣은 증거금만 담보로 쓰입니다. 손실이 커져 이 증거금이 ",["유지 증거금","maintenance-margin"]," 아래로 떨어지면 해당 포지션만 청산되고, 다른 포지션과 남은 잔고는 그대로입니다."],["최대 손실이 미리 정해진다는 장점이 있지만, 증거금이 적은 만큼 ",["교차 마진","cross-margin"],"보다 ",["청산가","liquidation-price"],"가 진입가에 가깝습니다. 필요하면 포지션에 증거금을 수동으로 추가해 청산가를 멀리 둘 수 있습니다."],["새로운 코인이나 변동이 큰 종목을 시험적으로 거래할 때, 또는 여러 포지션의 위험을 따로 관리하고 싶을 때 많이 씁니다. ",["거래소","centralized-exchange"],"에 따라 기본값이 교차 마진인 경우도 있어 주문 전에 모드를 확인해야 합니다."]],"example":["계좌에 5,000 USDT가 있고 격리 마진으로 500 USDT를 배정해 10배 ",["레버리지","leverage"]," ",["BTC","bitcoin"]," 롱(5,000 USDT 규모)을 열었다고 가정해 보겠습니다. BTC가 약 9% 넘게 떨어져 청산되면 잃는 금액은 배정한 500 USDT뿐이고, 나머지 4,500 USDT는 남습니다. 같은 포지션을 교차 마진으로 열었다면 청산가는 훨씬 멀어지지만, 그 대신 더 큰 손실이 계좌 잔고에서 빠져나갈 수 있습니다."],"mistakes":["격리 마진이면 손실이 작으니 높은 레버리지를 써도 된다고 생각해 사소한 변동에 청산됩니다.","증거금을 계속 추가하다가 결국 처음 정한 최대 손실보다 훨씬 많이 잃습니다.","주문 전 마진 모드를 확인하지 않아 의도와 달리 교차 마진으로 진입합니다."],"faq":[{"q":"격리 마진과 교차 마진 중 무엇이 안전한가요?","a":"격리 마진은 최대 손실이 해당 포지션 증거금으로 제한되고, 교차 마진은 청산가가 멀지만 계좌 전체가 담보가 됩니다. 손실 한도를 명확히 하고 싶다면 격리 마진이 관리하기 쉽습니다."},{"q":"격리 마진에서 청산가를 멀리 할 수 있나요?","a":"포지션에 증거금을 추가하거나 레버리지를 낮추면 청산가가 진입가에서 멀어집니다. 다만 추가한 증거금도 청산 시 함께 잃을 수 있습니다."}],"title":"격리 마진이란? 교차 마진과의 차이","description":"격리 마진의 뜻, 포지션별로 증거금을 나누는 방식, 교차 마진과 청산가 차이와 사용 시 주의점을 설명합니다.","related":[["cross-margin","교차 마진(Cross Margin)","교차 마진은 계좌의 사용 가능한 잔고 전체를 여러 포지션이 함께 증거금으로 쓰는 방식으로, 청산가는 멀어지지만 한 번 청산되면 계좌 잔고 대부분을 잃을 수 있습니다."],["portfolio-margin","포트폴리오 마진(Portfolio Margin)","포트폴리오 마진은 개별 포지션이 아니라 계좌 전체 포지션의 순위험을 계산해 필요한 증거금을 정하는 방식으로, 서로 상쇄되는 포지션이 많을수록 증거금 부담이 줄어듭니다."],["liquidation-price","청산가(Liquidation Price)","청산가는 마크 가격이 그 수준에 닿으면 증거금이 유지 증거금 아래로 떨어져 포지션이 강제청산되는 가격입니다."],["leverage","레버리지(Leverage)","레버리지는 맡긴 증거금보다 몇 배 큰 규모의 포지션을 거래하는 것으로, 수익과 손실이 모두 그 배수만큼 커지고 강제청산 위험도 함께 커집니다."]],"lesson":{"id":"E21","slug":"isolated-margin","ep":21,"title":"격리 마진: 이 거래를 독립된 작은 상자에 담기"},"coin":null,"tool":null,"cta":false},"index-price":{"slug":"index-price","cat":"derivatives","en":"Index price","contentLocale":"ko","term":"지수 가격(Index Price)","aka":["인덱스 가격","index price","현물 지수"],"short":"지수 가격은 여러 주요 현물 거래소의 가격을 가중 평균해 만든 기준 가격으로, 선물의 마크 가격과 펀딩비를 계산하는 바탕이 됩니다.","body":[[["거래소","centralized-exchange"],"는 신뢰할 만한 ",["현물 거래","spot-trading"],"소 여러 곳을 골라 각 가격을 일정한 가중치로 평균합니다. 한 거래소에서 가격이 비정상적으로 튀면 그 거래소를 제외하거나 가중치를 낮추는 규칙을 두는 경우가 많습니다."],[["무기한 선물","perpetual-futures"],"의 ",["펀딩비","funding-rate"],"는 선물 가격이 지수 가격보다 얼마나 높거나 낮은지를 반영해 정해집니다. ",["마크 가격","mark-price"],"도 지수 가격을 중심으로 계산되므로, 지수 가격은 청산과 손익 평가의 뿌리라고 할 수 있습니다."],["어떤 거래소들을 어떤 비중으로 쓰는지는 거래소마다 공개하는 지수 구성표에서 확인할 수 있습니다. ",["탈중앙화 거래소","dex"],"는 오라클이라는 외부 가격 공급 장치를 통해 비슷한 역할의 가격을 가져옵니다."]],"example":"어떤 거래소의 BTC 지수가 세 현물 거래소 가격을 같은 비중으로 평균한다고 가정해 보겠습니다. 각 가격이 65,000, 65,060, 64,970 USDT라면 지수 가격은 (65,000 + 65,060 + 64,970) ÷ 3 = 65,010 USDT입니다. 이때 그 거래소 무기한 선물이 65,200 USDT에 거래되면 선물이 지수보다 약 0.29% 높은 상태로, 펀딩비가 플러스 쪽으로 움직이기 쉽습니다.","mistakes":["지수 가격을 특정 한 거래소의 현물 가격으로 착각합니다.","선물 가격과 지수 가격의 차이를 무시하고 펀딩비 방향을 예상합니다.","구성 거래소 중 한 곳에 문제가 생기면 지수가 어떻게 처리되는지 확인하지 않습니다."],"faq":[{"q":"지수 가격과 마크 가격은 같은 건가요?","a":"다릅니다. 지수 가격은 현물 가격의 평균이고, 마크 가격은 지수 가격에 펀딩이나 베이시스 요소를 반영해 청산 기준으로 쓰는 가격입니다. 평소에는 두 값이 매우 가깝습니다."},{"q":"지수 가격은 어디서 볼 수 있나요?","a":"대부분의 거래소 선물 화면에서 지수 가격, 마크 가격, 최근 체결가를 함께 보여 줍니다. 지수 구성 거래소 목록은 거래소의 안내 페이지에서 확인할 수 있습니다."}],"title":"지수 가격이란? 마크 가격·펀딩비와의 관계","description":"선물 거래소 지수 가격의 뜻, 여러 현물 거래소 가격으로 계산하는 방법, 마크 가격과 펀딩비와의 관계를 설명합니다.","related":[["mark-price","마크 가격(Mark Price)","마크 가격은 선물 거래소가 평가 손익과 강제청산을 계산할 때 쓰는 기준 가격으로, 여러 현물 거래소의 지수 가격을 바탕으로 만들어 순간적인 가격 조작의 영향을 줄입니다."],["last-price","최근 체결가(Last Price)","최근 체결가는 해당 거래소 시장에서 가장 마지막으로 실제 체결된 거래의 가격으로, 차트와 시세 화면에 현재가로 표시되는 값입니다."],["funding-rate","펀딩비(Funding Rate)","펀딩비는 무기한 선물에서 롱과 숏 포지션 보유자가 일정 간격마다 서로 주고받는 비용으로, 선물 가격이 현물 가격에서 크게 벗어나지 않도록 하는 장치입니다."],["oracle","블록체인 오라클(Oracle)","블록체인 오라클은 코인 가격, 환율, 경기 결과처럼 블록체인 밖에 있는 데이터를 스마트 컨트랙트가 읽을 수 있도록 체인 위로 전달하는 시스템입니다."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"강제 청산: 강제 종료 버튼은 누가 눌렀는가?"},"coin":null,"tool":"/funding-rates","cta":false},"yield-farming":{"slug":"yield-farming","cat":"defi","en":"Yield farming","contentLocale":"ko","term":"일드 파밍(Yield Farming)","aka":["이자 농사","파밍","yield farming"],"short":"일드 파밍은 디파이 프로토콜에 자산을 예치하거나 유동성을 공급하고 그 대가로 이자, 수수료, 보상 토큰을 받아 수익을 쌓는 전략입니다.","body":[["가장 흔한 방식은 ",["유동성 풀","liquidity-pool"],"에 자산을 넣고 받은 LP 토큰을 다시 팜(Farm) ",["컨트랙트","smart-contract"],"에 ",["스테이킹","staking"],"해 프로토콜 보상 토큰을 받는 것입니다. 대출 프로토콜 예치, 여러 프로토콜을 오가는 재예치도 일드 파밍에 포함됩니다."],"높은 수익률은 대개 새로 발행되는 보상 토큰에서 나옵니다. 보상 토큰 가격이 떨어지면 표시된 연 수익률과 실제 수익이 크게 달라질 수 있습니다. 참여자가 늘면 보상이 나뉘어 수익률도 내려갑니다.",["위험은 겹겹이 쌓입니다. 스마트 컨트랙트 위험이 프로토콜 수만큼 늘고, ",["비영구적 손실","impermanent-loss"],", 보상 토큰 하락, ",["가스비","gas-fee"],"가 함께 작용합니다. 수익률 숫자보다 수익이 어디서 나오는지를 먼저 확인하는 것이 중요합니다."]],"example":["10,000 USDC를 연 40%라고 표시된 팜에 넣었다고 가정합니다. 이 중 5%는 거래 수수료, 35%는 보상 토큰 R에서 나옵니다. 1년 뒤 수수료로 500 ",["USDC","usdc"],", 보상 토큰으로 처음 가격 기준 3,500 USDC어치를 받지만, 그사이 R 가격이 60% 떨어졌다면 보상 가치는 1,400 USDC입니다. 실제 수익은 약 1,900 USDC로 19% 수준이며, 비영구적 손실과 가스비를 빼면 더 줄어듭니다."],"mistakes":["연 수익률 숫자가 높을수록 좋은 팜이라고 판단합니다.","보상 토큰을 계속 쌓기만 하고 가격 하락을 고려하지 않습니다.","소액으로 자주 재예치해 가스비가 수익을 넘어섭니다."],"faq":[{"q":"일드 파밍과 스테이킹의 차이는 무엇인가요?","a":"스테이킹은 지분증명 블록체인의 검증에 참여해 보상을 받는 것이고, 일드 파밍은 디파이 프로토콜에 유동성을 제공하고 수수료와 보상 토큰을 받는 것입니다. 일드 파밍은 보통 위험 요소가 더 많습니다."},{"q":"일드 파밍 수익률이 왜 이렇게 자주 바뀌나요?","a":"보상 토큰 가격, 참여 자금 규모, 거래량이 계속 변하기 때문입니다. 화면 수치는 현재 조건을 연환산한 추정치입니다."}],"title":"일드 파밍이란? 디파이 이자 농사 구조","description":"일드 파밍의 뜻과 수익이 나오는 곳, 보상 토큰 하락과 비영구적 손실 등 높은 수익률 뒤에 숨은 위험을 설명합니다.","related":[["liquidity-pool","유동성 풀(Liquidity Pool)","유동성 풀은 DEX에서 거래가 가능하도록 두 가지 이상의 토큰을 스마트 컨트랙트에 함께 예치해 둔 자금 저장소로, 공급자는 거래 수수료를 나눠 받습니다."],["apr-vs-apy","APR과 APY의 차이","APR은 복리를 반영하지 않은 단순 연이율이고, APY는 받은 이자를 다시 굴리는 복리 효과까지 반영한 연 수익률입니다."],["impermanent-loss","비영구적 손실(Impermanent Loss)","비영구적 손실은 유동성 풀에 넣은 두 토큰의 가격 비율이 변했을 때, 그냥 지갑에 들고 있었던 경우보다 풀에서 꺼낸 자산 가치가 줄어드는 현상입니다."],["staking","스테이킹(Staking)","스테이킹은 지분증명(PoS) 블록체인에서 코인을 맡겨 네트워크 검증에 참여하거나 검증인에게 위임하고 그 대가로 보상을 받는 방법입니다."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"mev":{"slug":"mev","cat":"defi","en":"MEV (maximal extractable value)","contentLocale":"ko","term":"MEV(최대 추출 가능 가치)","aka":["MEV","샌드위치 공격","maximal extractable value"],"short":"MEV는 블록 생성자나 봇이 블록 안 거래의 순서를 정하거나 끼워 넣어 얻을 수 있는 추가 이익을 말하며, 샌드위치 공격이 대표적인 예입니다.","body":[["거래는 블록에 들어가기 전 ",["멤풀","mempool"],"에서 공개적으로 대기합니다. 봇은 이 대기 거래를 보고 더 높은 수수료를 내 내 거래 앞에 자기 거래를 넣거나, 뒤에 붙여 차익을 얻습니다. 이렇게 거래 순서에서 나오는 이익이 MEV입니다."],["모든 MEV가 해로운 것은 아닙니다. ",["거래소","centralized-exchange"]," 간 가격 차를 메우는 ",["차익거래","arbitrage"],"나 ",["디파이","defi"]," 청산 처리도 MEV에 포함되고, 시장 효율을 높이는 면이 있습니다. 문제는 샌드위치 공격처럼 일반 사용자에게 직접 비용을 떠넘기는 경우입니다."],["샌드위치 공격은 내 ",["슬리피지","slippage"]," 허용치만큼 가격을 밀어 올린 뒤 내 거래가 체결되면 바로 팔아 차익을 챙깁니다. 슬리피지 허용치를 필요 이상으로 높이지 않고, 지원되는 경우 MEV 보호 RPC나 프라이빗 전송 기능을 쓰면 피해를 줄일 수 있습니다."]],"example":["DEX에서 20,000 USDC로 ETH를 사려는데 예상 수령량이 6.00 ETH이고 슬리피지 허용치를 2%로 설정했다고 가정합니다. 최소 수령량은 5.88 ETH입니다. 봇이 내 거래 직전에 ETH를 사서 가격을 올리고, 내 거래는 5.90 ETH로 체결되며, 봇은 바로 ETH를 팔아 차익을 얻습니다. 나는 0.10 ",["ETH","ethereum"],", ETH당 약 3,333 USDC 기준으로 약 333 USDC를 덜 받은 셈입니다. 허용치를 0.5%로 낮췄다면 봇이 끼어들 여지가 크게 줄었을 것입니다."],"mistakes":["거래가 실패할까 봐 슬리피지 허용치를 5% 이상으로 습관적으로 설정합니다.","MEV를 해킹으로만 이해하고 내 거래 설정과의 관계를 놓칩니다.","유동성이 얕은 풀에서 큰 금액을 공개 멤풀로 거래합니다."],"faq":[{"q":"샌드위치 공격을 당했는지 어떻게 알 수 있나요?","a":"블록 익스플로러에서 내 거래 바로 앞뒤로 같은 주소가 같은 토큰을 사고판 기록이 있으면 샌드위치 공격일 가능성이 높습니다."},{"q":"MEV 피해를 줄이는 방법은 무엇인가요?","a":"슬리피지 허용치를 낮게 잡고, 큰 주문은 나눠 실행하며, MEV 보호 기능을 지원하는 지갑이나 RPC를 사용하는 방법이 있습니다."}],"title":"MEV란? 샌드위치 공격 원리와 예방법","description":"MEV(최대 추출 가능 가치)의 뜻과 샌드위치 공격이 일어나는 과정, 슬리피지 설정으로 피해를 줄이는 방법을 설명합니다.","related":[["mempool","멤풀(Mempool)","멤풀은 블록에 아직 포함되지 않은 거래들이 노드마다 대기하는 공간으로, 채굴자나 검증자가 여기서 거래를 골라 블록을 만듭니다."],["slippage","슬리피지(Slippage)","슬리피지는 주문할 때 예상한 가격과 실제로 체결된 평균 가격의 차이로, 호가가 얇거나 가격이 빠르게 움직일 때 커집니다."],["dex","탈중앙화 거래소(DEX)","탈중앙화 거래소(DEX)는 회사가 자산을 보관하지 않고 사용자가 개인 지갑에서 스마트 컨트랙트와 직접 토큰을 교환하는 거래소입니다."],["gas-fee","가스비(Gas Fee)","가스비는 블록체인에서 송금이나 스마트 컨트랙트를 실행할 때 검증자나 채굴자에게 내는 네트워크 수수료로, 보통 그 체인의 기본 코인으로 지불합니다."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"nft":{"slug":"nft","cat":"defi","en":"NFT (non-fungible token)","contentLocale":"ko","term":"NFT(대체 불가능 토큰)","aka":["NFT","대체 불가능 토큰","논펀저블 토큰"],"short":"NFT(대체 불가능 토큰)는 각각 고유한 ID를 가져 서로 바꿔 쓸 수 없는 블록체인 토큰으로, 디지털 그림, 게임 아이템, 멤버십 같은 소유 기록에 쓰입니다.","body":[[["비트코인","bitcoin"],"이나 USDT는 1개끼리 서로 똑같아 바꿔도 차이가 없지만, NFT는 토큰마다 번호와 정보가 달라 하나하나가 별개입니다. ",["이더리움","ethereum"],"의 ERC-721, ERC-1155 표준이 널리 쓰이고 솔라나 등 다른 체인에도 NFT가 있습니다."],["NFT가 증명하는 것은 ",["블록체인","blockchain"],"상 그 토큰의 소유 기록입니다. 이미지 파일 자체는 별도 서버나 분산 저장소에 있는 경우가 많고, 저작권이 함께 넘어오는지는 프로젝트 약관에 따라 다릅니다."],["NFT 거래에서는 마켓플레이스 수수료, 창작자 로열티, ",["가스비","gas-fee"],"가 듭니다. ",["거래량","trading-volume"],"이 적은 컬렉션은 원하는 가격에 팔기 어려운 ",["유동성","liquidity"]," 문제도 큽니다. 무료 민팅이나 에어드랍을 가장한 피싱, 가짜 컬렉션도 흔하니 컨트랙트 주소를 확인해야 합니다."]],"example":"NFT 하나를 0.5 ETH에 사서 나중에 0.8 ETH에 판다고 가정합니다. 마켓플레이스 수수료 2.5%, 창작자 로열티 5%가 적용되면 판매 대금에서 7.5%인 0.06 ETH가 빠져 0.74 ETH를 받습니다. 매수와 판매 때 가스비를 합쳐 0.01 ETH 썼다면 순이익은 0.74에서 0.5와 0.01을 뺀 0.23 ETH입니다. 수수료와 로열티 비율은 마켓플레이스와 컬렉션 설정에 따라 다릅니다.","mistakes":["NFT를 사면 그림의 저작권까지 자동으로 갖는다고 생각합니다.","바닥 가격만 보고 실제 거래량이 거의 없다는 점을 확인하지 않습니다.","무료 민팅 링크에서 지갑의 모든 NFT 전송 권한을 승인합니다."],"faq":[{"q":"NFT를 사면 무엇을 소유하게 되나요?","a":"블록체인에 기록된 특정 토큰의 소유권을 갖게 됩니다. 이미지 사용 권리나 저작권 범위는 프로젝트마다 다르므로 약관을 확인해야 합니다."},{"q":"NFT 바닥 가격이란 무엇인가요?","a":"해당 컬렉션에서 현재 판매 중인 NFT 가운데 가장 낮은 가격입니다. 바닥 가격이 있어도 그 가격에 바로 팔린다는 보장은 없습니다."}],"title":"NFT란? 대체 불가능 토큰 뜻과 거래 비용","description":"NFT(대체 불가능 토큰)의 뜻, 소유권과 저작권의 차이, 수수료와 로열티 계산, NFT 피싱 주의점을 설명합니다.","related":[["smart-contract","스마트 컨트랙트(Smart Contract)","스마트 컨트랙트는 블록체인에 배포되어 미리 정한 조건이 충족되면 자동으로 실행되는 프로그램으로, 중개자 없이 거래와 규칙을 처리합니다."],["token-approval","토큰 승인(Token Approval, 허용량)","토큰 승인은 스마트 컨트랙트가 내 지갑의 특정 토큰을 정해진 한도만큼 대신 옮길 수 있도록 허락하는 서명으로, 한 번 주면 취소하기 전까지 유지됩니다."],["phishing","피싱(Phishing)","피싱은 가짜 웹사이트, 메일, 메시지, 광고로 공식 서비스인 척 접근해 비밀번호, 시드 문구, 지갑 서명을 빼내는 사기 수법입니다."],["coin-vs-token","코인과 토큰의 차이(Coin vs Token)","코인은 자체 블록체인의 기본 자산(예: BTC, ETH)이고, 토큰은 다른 블록체인 위에서 스마트 컨트랙트로 발행된 자산(예: 이더리움 위의 USDT)입니다."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"vasp":{"slug":"vasp","cat":"regulation","en":"VASP (virtual asset service provider)","contentLocale":"ko","term":"VASP(가상자산사업자)","aka":["가상자산사업자","가상자산 서비스 제공자","VASP"],"short":"VASP는 가상자산의 매매, 교환, 이전, 보관 같은 서비스를 다른 사람을 위해 제공하는 사업자로, 거래소와 수탁 지갑 업체가 대표적입니다.","body":[["FATF가 정의한 용어로, 각국은 VASP에 등록이나 인가를 받게 하고 ",["KYC","kyc"],", ",["자금세탁방지","aml"],", ",["트래블룰","travel-rule"]," 의무를 부과합니다. 한국에서는 특정금융정보법에 따라 금융정보분석원(FIU)에 가상자산사업자 신고를 해야 하며, 정보보호 관리체계(ISMS) 인증과 원화 거래 시 실명 계좌 요건이 따릅니다. EU의 MiCA에서는 비슷한 개념을 CASP라고 부릅니다."],"사용자에게 중요한 이유는 보호 수준 때문입니다. 신고나 인가를 받은 사업자는 고객 자산 분리 보관, 보안 기준, 감독 기관 검사 같은 의무를 집니다. 미신고 해외 사업자는 국내 이용자를 상대로 영업하는 것이 제한될 수 있고, 분쟁이 생겼을 때 국내에서 구제받기 어렵습니다.",["같은 ",["거래소","centralized-exchange"],"라도 나라별 법인과 라이선스가 따로 있는 경우가 많습니다. 내가 가입한 법인이 어느 나라 규제를 받는지 이용약관 하단에서 확인할 수 있습니다."]],"example":"사용자가 1,000만 원어치 코인을 두 곳에 나눠 둔다고 가정합니다. 국내에 신고된 거래소 A에 600만 원, 신고되지 않은 해외 플랫폼 B에 400만 원입니다. A에 문제가 생기면 감독 기관 검사 기록과 고객 자산 분리 의무가 있어 처리 절차가 비교적 명확합니다. B에 문제가 생기면 400만 원, 즉 전체의 40%가 어느 나라 법으로 다퉈야 할지부터 불분명할 수 있습니다.","mistakes":["앱스토어에 있으면 국내 신고를 마친 사업자라고 생각합니다.","글로벌 브랜드 이름만 보고 내가 계약한 법인이 어디인지 확인하지 않습니다.","VASP 등록이 원금 보장을 의미한다고 오해합니다."],"faq":[{"q":"신고된 가상자산사업자는 어디서 확인하나요?","a":"한국에서는 금융정보분석원이 신고 수리 현황을 공개합니다. 다른 나라도 금융 당국 웹사이트에서 등록 사업자 목록을 확인할 수 있습니다."},{"q":"VASP와 CASP는 무엇이 다른가요?","a":"기본 개념은 비슷합니다. VASP는 FATF와 여러 나라가 쓰는 용어이고, CASP는 EU MiCA 규정에서 쓰는 용어입니다."}],"title":"VASP란? 가상자산사업자 뜻과 신고 의미","description":"VASP(가상자산사업자)의 뜻, 한국 특금법 신고 요건과 MiCA의 CASP와의 차이, 이용자 보호 관점을 설명합니다.","related":[["kyc","KYC(고객확인제도)","KYC는 거래소 같은 금융 서비스가 고객의 신원을 확인하고 기록하는 절차로, 자금세탁 방지 규정에 따라 계정 개설이나 입출금 전에 요구됩니다."],["mica","MiCA(EU 가상자산시장법)","MiCA는 유럽연합이 만든 가상자산 시장 규정으로, 스테이블코인 발행사와 가상자산 서비스 제공자(CASP)에 대한 인가와 운영 기준을 EU 전체에 통일했습니다."],["travel-rule","트래블룰(Travel rule)","트래블룰은 가상자산을 다른 사업자에게 보낼 때 보내는 사람과 받는 사람의 정보를 함께 전달하도록 요구하는 자금세탁방지 규칙입니다."],["centralized-exchange","중앙화 거래소(CEX)","중앙화 거래소(CEX)는 회사가 운영하며 사용자의 자산을 보관하고 주문을 자체 시스템에서 체결해 주는 암호화폐 거래소입니다."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"진짜 문을 찾으세요: 무작정 계정을 만들지 마세요"},"coin":null,"tool":"/topics/compliant-exchanges","cta":false},"mica":{"slug":"mica","cat":"regulation","en":"MiCA (EU Markets in Crypto-Assets)","contentLocale":"ko","term":"MiCA(EU 가상자산시장법)","aka":["미카","EU 가상자산 규제","MiCA"],"short":"MiCA는 유럽연합이 만든 가상자산 시장 규정으로, 스테이블코인 발행사와 가상자산 서비스 제공자(CASP)에 대한 인가와 운영 기준을 EU 전체에 통일했습니다.","body":[[["스테이블코인","stablecoin"]," 관련 규정은 2024년 6월 30일부터, ",["거래소","centralized-exchange"],"와 수탁 업체 같은 CASP 규정은 2024년 12월 30일부터 적용되었습니다. 기존 사업자에게는 나라별로 최대 2026년 7월 1일까지 전환 기간이 주어졌습니다. 한 회원국에서 인가를 받으면 다른 EU 회원국에서도 영업할 수 있는 패스포팅이 핵심입니다."],["스테이블코인 쪽에서는 발행사가 인가를 받고 준비금 요건을 지켜야 합니다. 그래서 EU에서 인가받은 ",["USDC","usdc"]," 같은 스테이블코인과 그렇지 않은 스테이블코인의 취급이 달라졌고, 일부 거래소는 EU 사용자에게 미인가 스테이블코인 거래를 제한했습니다."],"한국 거주자에게 MiCA가 직접 적용되지는 않습니다. 다만 글로벌 거래소가 MiCA에 맞춰 상품 구성과 약관을 바꾸면 다른 지역 서비스에도 영향을 줄 수 있고, 규제 수준을 비교하는 기준으로도 자주 언급됩니다."],"example":"EU에 사는 사용자가 거래소에서 스테이블코인 A 5,000개와 B 5,000개를 보유하고 있다고 가정합니다. A는 MiCA 인가를 받은 발행사의 코인이고 B는 아닙니다. 거래소가 B의 EU 내 거래를 정리하기로 하면 사용자는 기한 안에 B를 A나 다른 자산으로 바꾸거나 출금해야 합니다. 이때 전환 수수료가 0.1%라면 5,000개 기준 약 5개를 비용으로 내게 됩니다. 실제 일정과 방식은 거래소 공지를 따릅니다.","mistakes":["MiCA 인가가 거래소 파산 시 자산을 전액 보장한다고 생각합니다.","MiCA가 전 세계 모든 거래소에 적용된다고 오해합니다.","전환 기간이 나라마다 다르다는 점을 모르고 일정을 하나로 계산합니다."],"faq":[{"q":"MiCA는 언제부터 시행됐나요?","a":"스테이블코인 규정은 2024년 6월 30일, 서비스 제공자 규정은 2024년 12월 30일부터 적용됐습니다. 기존 사업자는 나라별로 최대 2026년 7월 1일까지 전환 기간이 있었습니다."},{"q":"MiCA 때문에 USDT 거래가 막혔나요?","a":"일부 거래소가 EU 사용자에게 MiCA 미인가 스테이블코인 거래를 제한했습니다. 적용 범위와 시점은 거래소마다 다릅니다."}],"title":"MiCA란? EU 가상자산 규제와 스테이블코인 영향","description":"MiCA(EU 가상자산시장법)의 뜻, 적용 일정, 스테이블코인과 거래소에 미친 영향을 정리했습니다.","related":[["vasp","VASP(가상자산사업자)","VASP는 가상자산의 매매, 교환, 이전, 보관 같은 서비스를 다른 사람을 위해 제공하는 사업자로, 거래소와 수탁 지갑 업체가 대표적입니다."],["stablecoin","스테이블코인(Stablecoin)","스테이블코인은 미국 달러 같은 법정화폐나 다른 자산의 가치에 가격을 고정하도록 설계된 암호화폐로, USDT와 USDC가 대표적입니다."],["usdc","USDC(USD 코인)","USDC는 미국 기업 서클(Circle)이 발행하는 미국 달러 연동 스테이블코인으로, 현금과 단기 미국 국채 등 준비자산으로 1대1 가치를 뒷받침합니다."],["kyc","KYC(고객확인제도)","KYC는 거래소 같은 금융 서비스가 고객의 신원을 확인하고 기록하는 절차로, 자금세탁 방지 규정에 따라 계정 개설이나 입출금 전에 요구됩니다."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"진짜 문을 찾으세요: 무작정 계정을 만들지 마세요"},"coin":null,"tool":null,"cta":false},"dual-investment":{"slug":"dual-investment","cat":"exchange-features","en":"Dual investment","contentLocale":"ko","term":"이중 투자(Dual investment)","aka":["듀얼 인베스트먼트","이중 통화 투자","Dual investment"],"short":"이중 투자는 목표 가격과 만기를 정해 코인이나 스테이블코인을 맡기면, 만기 시 가격에 따라 원래 자산 또는 다른 자산으로 원금과 보상을 돌려받는 구조화 상품입니다.","body":["두 가지 방향이 있습니다. 싸게 사기는 USDT를 맡기고 목표 가격 아래로 내려가면 그 가격에 코인을 사는 방식이고, 비싸게 팔기는 코인을 맡기고 목표 가격 위로 오르면 그 가격에 파는 방식입니다. 어느 경우든 높은 보상을 받지만 어떤 자산으로 돌려받을지는 만기 가격이 결정합니다.","구조적으로는 사용자가 옵션을 파는 것과 비슷합니다. 높은 보상은 가격이 크게 움직일 때의 기회를 포기한 대가입니다. 가격이 목표를 훨씬 넘어가도 정해진 가격에만 거래되고, 크게 떨어지면 떨어진 코인을 목표 가격에 산 셈이 됩니다.",["대부분 만기 전 해지가 불가능하거나 제한적이며, 표시 수익률은 연 환산 수치라 실제로 받는 보상은 기간에 비례해 작습니다. 정산 기준 가격과 시각은 ",["거래소","centralized-exchange"],"마다 다릅니다."]],"example":["BTC가 62,000 USDT일 때 10,000 USDT로 7일 만기, 목표 가격 60,000 ",["USDT","usdt"],", 연 환산 36%의 싸게 사기 상품에 가입했다고 가정합니다. 7일 보상은 10,000 × 36% × 7 ÷ 365 ≈ 69 USDT입니다. 만기 가격이 60,000 이상이면 10,069 USDT를 돌려받습니다. 만기 가격이 55,000이면 10,069 ÷ 60,000 ≈ 0.1678 BTC를 받고, 그 가치는 약 9,230 USDT로 원금보다 약 770 USDT 적습니다."],"mistakes":["연 환산 수익률을 실제 기간 수익으로 착각합니다.","원금이 항상 같은 자산으로 돌아온다고 생각합니다.","목표 가격에 사거나 팔아도 괜찮은지 따져 보지 않고 높은 이율만 보고 가입합니다."],"faq":[{"q":"이중 투자는 원금 보장 상품인가요?","a":"아닙니다. 수량 기준으로는 보상이 붙지만, 다른 자산으로 전환되어 돌아오면 시장 가치 기준으로 손실이 날 수 있습니다."},{"q":"이중 투자는 만기 전에 해지할 수 있나요?","a":"대부분 만기까지 묶이며, 일부 거래소만 조건부 조기 상환을 지원합니다. 가입 전에 상품 설명에서 확인해야 합니다."}],"title":"이중 투자(Dual investment)란? 구조와 손익 계산","description":"이중 투자의 뜻, 싸게 사기·비싸게 팔기 구조, 연 환산 수익률과 만기 시 손익 계산 예시를 설명합니다.","related":[["options","코인 옵션(Crypto Options)","코인 옵션은 정해진 만기일에 미리 정한 가격(행사가)으로 코인을 사거나 팔 수 있는 권리를 사고파는 파생상품으로, 사는 권리는 콜옵션, 파는 권리는 풋옵션이라고 합니다."],["crypto-earn","거래소 예치 상품(Crypto Earn)","거래소 예치 상품은 거래소에 코인을 맡기면 정해진 기간이나 자유 입출금 조건으로 이자 성격의 보상을 주는 상품군을 말합니다."],["apr-vs-apy","APR과 APY의 차이","APR은 복리를 반영하지 않은 단순 연이율이고, APY는 받은 이자를 다시 굴리는 복리 효과까지 반영한 연 수익률입니다."],["volatility","변동성(Volatility)","변동성은 일정 기간 동안 가격이 얼마나 크고 빠르게 오르내리는지를 나타내는 정도로, 변동성이 클수록 같은 기간에 가격이 더 크게 움직입니다."]],"lesson":null,"coin":null,"tool":null,"cta":false},"unified-trading-account":{"slug":"unified-trading-account","cat":"exchange-features","en":"Unified trading account (UTA)","contentLocale":"ko","term":"통합 거래 계정(UTA)","aka":["통합 계정","통합 마진 계정","UTA","Unified trading account"],"short":"통합 거래 계정은 현물, 선물, 옵션 거래를 하나의 계정 잔고와 증거금으로 함께 운용할 수 있게 묶은 거래소 계정 방식입니다.","body":[["예전에는 현물 계정과 선물 계정이 나뉘어 있어 선물 거래를 하려면 자금을 옮겨야 했습니다. 통합 거래 계정에서는 보유 중인 BTC나 ",["ETH","ethereum"]," 같은 현물 자산도 할인율을 적용해 증거금으로 인정받고, 한 상품의 이익이 다른 상품의 손실을 메워 줄 수 있습니다. Bybit, OKX 등이 이런 계정 방식을 제공합니다."],["자금 효율이 높아지는 대신 위험도 연결됩니다. 선물에서 큰 손실이 나면 계정 전체의 증거금 비율이 떨어지고, 심하면 현물로 들고 있던 코인까지 청산에 쓰일 수 있습니다. ",["교차 마진","cross-margin"],"과 비슷한 구조라고 이해하면 됩니다."],["계정 모드에는 보통 일반, 교차 마진, ",["포트폴리오 마진","portfolio-margin"]," 같은 단계가 있고, 담보로 인정되는 코인과 할인율, 이자 계산 방식이 ",["거래소","centralized-exchange"],"마다 다릅니다. 특정 포지션만 따로 위험을 묶고 싶다면 ",["격리 마진","isolated-margin"],"이나 ",["서브 계정","sub-account"],"을 함께 쓰는 방법이 있습니다."]],"example":"통합 계정에 USDT 2,000개와 0.1 BTC가 있고, BTC 가격이 60,000 USDT, 담보 할인율이 95%라고 가정합니다. BTC의 담보 인정 가치는 0.1 × 60,000 × 95% = 5,700 USDT이므로 총 증거금은 7,700 USDT입니다. 선물 포지션에서 6,000 USDT 손실이 나고 BTC가 50,000 USDT로 내려가면 BTC 담보 가치는 4,750 USDT가 되어 남은 증거금이 크게 줄고, 유지 증거금에 못 미치면 BTC까지 청산될 수 있습니다.","mistakes":["장기 보관용 현물 코인이 선물 증거금으로 쓰이고 있다는 점을 모릅니다.","담보 할인율 때문에 실제 인정 가치가 표시 잔고보다 낮다는 점을 놓칩니다.","계정 모드를 바꿀 때 열린 포지션과 대출 조건이 어떻게 달라지는지 확인하지 않습니다."],"faq":[{"q":"통합 거래 계정은 꼭 써야 하나요?","a":"필수는 아니지만 여러 상품을 함께 거래한다면 자금 이동이 줄어 편리합니다. 위험을 분리하고 싶다면 서브 계정이나 격리 마진을 함께 쓰세요."},{"q":"통합 계정에서 현물이 청산될 수 있나요?","a":"계정 전체 증거금이 부족해지면 담보로 인정된 현물 자산이 청산에 쓰일 수 있습니다. 구체적인 순서는 거래소 규칙에 따릅니다."}],"title":"통합 거래 계정(UTA)이란? 증거금 공유와 위험","description":"통합 거래 계정(UTA)의 뜻, 현물을 담보로 쓰는 원리와 할인율 계산, 현물까지 청산되는 경우를 설명합니다.","related":[["cross-margin","교차 마진(Cross Margin)","교차 마진은 계좌의 사용 가능한 잔고 전체를 여러 포지션이 함께 증거금으로 쓰는 방식으로, 청산가는 멀어지지만 한 번 청산되면 계좌 잔고 대부분을 잃을 수 있습니다."],["portfolio-margin","포트폴리오 마진(Portfolio Margin)","포트폴리오 마진은 개별 포지션이 아니라 계좌 전체 포지션의 순위험을 계산해 필요한 증거금을 정하는 방식으로, 서로 상쇄되는 포지션이 많을수록 증거금 부담이 줄어듭니다."],["sub-account","서브 계정(Sub-account)","서브 계정은 하나의 메인 계정 아래에 만드는 별도 거래 계정으로, 자금과 포지션, API 키를 전략별로 분리해 관리할 수 있게 해 줍니다."],["margin-trading","마진 거래(Margin Trading)","마진 거래는 계좌의 자산을 증거금으로 맡기고 거래소에서 자금을 빌려 보유 자금보다 큰 규모로 사거나, 코인을 빌려 팔아 하락에 베팅하는 거래입니다."]],"lesson":null,"coin":null,"tool":null,"cta":true},"withdrawal-fee":{"slug":"withdrawal-fee","cat":"exchange-features","en":"Withdrawal fee","contentLocale":"ko","term":"출금 수수료","aka":["출금 수수료","출금비","Withdrawal fee"],"short":"출금 수수료는 거래소에서 코인을 외부 지갑이나 다른 거래소로 보낼 때 출금 수량에서 차감되는 비용으로, 코인과 네트워크마다 다르게 정해집니다.","body":[["출금 수수료는 ",["블록체인","blockchain"]," 네트워크에 내는 ",["가스비","gas-fee"],"를 ",["거래소","centralized-exchange"],"가 대신 처리하는 비용에 운영 비용을 더한 것입니다. 대부분 비율이 아니라 고정 수량으로 정해져 있어, 100 USDT를 보내든 10,000 USDT를 보내든 같은 금액이 빠지는 경우가 많습니다."],["같은 코인이라도 어떤 네트워크로 보내느냐에 따라 수수료가 크게 다릅니다. USDT는 ",["이더리움","ethereum"],"(ERC20), 트론(TRC20), 솔라나, 여러 ",["레이어2","layer-2"]," 네트워크로 출금할 수 있는데, 이더리움 ",["메인넷","layer-1"],"이 대개 가장 비싸고 다른 네트워크가 저렴한 편입니다. 다만 받는 쪽이 그 네트워크를 지원해야 하고, 잘못 선택하면 자산을 잃을 수 있습니다."],"거래소는 네트워크 혼잡도에 따라 수수료를 수시로 조정합니다. 최소 출금 수량도 함께 정해져 있으니 출금 화면에서 실제 차감 금액과 받는 수량을 확인하세요."],"example":"USDT 300개를 다른 거래소로 옮긴다고 가정합니다. 출금 화면에서 ERC20 수수료가 4 USDT, TRC20이 1 USDT, 어떤 레이어2 네트워크가 0.2 USDT로 표시됩니다. ERC20으로 보내면 296 USDT, TRC20은 299 USDT, 레이어2는 299.8 USDT가 도착합니다. 한 달에 열 번 옮긴다면 ERC20과 레이어2의 차이는 38 USDT입니다. 단, 받는 거래소가 해당 레이어2 입금을 지원하는지 먼저 확인해야 합니다.","mistakes":["가장 싼 네트워크를 고르면서 받는 쪽이 그 네트워크를 지원하는지 확인하지 않습니다.","출금 수수료가 비율이라고 생각해 소액을 여러 번 나눠 보냅니다.","받는 수량이 아니라 출금 신청 수량을 기준으로 상대방에게 금액을 맞춰 보냅니다."],"faq":[{"q":"출금 수수료가 가장 싼 네트워크는 무엇인가요?","a":"시점과 거래소마다 다릅니다. 출금 화면에서 네트워크별 수수료를 비교하고, 받는 쪽이 지원하는 네트워크 중에서 고르세요."},{"q":"출금 수수료는 왜 거래소마다 다른가요?","a":"가스비에 더해 거래소별 운영 비용과 정책이 반영되기 때문입니다. 같은 코인, 같은 네트워크라도 차이가 날 수 있습니다."}],"title":"출금 수수료란? 네트워크별 비용 비교와 절약법","description":"거래소 출금 수수료의 뜻, 고정 수량으로 빠지는 이유, ERC20·TRC20 등 네트워크별 비용 비교법을 설명합니다.","related":[["gas-fee","가스비(Gas Fee)","가스비는 블록체인에서 송금이나 스마트 컨트랙트를 실행할 때 검증자나 채굴자에게 내는 네트워크 수수료로, 보통 그 체인의 기본 코인으로 지불합니다."],["blockchain-network","입금 네트워크(체인 선택)","입금 네트워크는 같은 코인을 어떤 블록체인으로 보낼지 고르는 설정으로, 보내는 쪽과 받는 쪽의 네트워크가 반드시 같아야 합니다."],["maker-taker-fees","메이커·테이커 수수료(Maker/Taker Fee)","메이커·테이커 수수료는 호가창에 새 주문을 걸어 유동성을 공급한 쪽(메이커)과 이미 걸린 주문을 즉시 체결한 쪽(테이커)에 서로 다르게 매기는 거래 수수료입니다."],["layer-2","레이어2(Layer 2, L2)","레이어2(L2)는 레이어1 블록체인 위에서 거래를 더 빠르고 저렴하게 처리한 뒤, 그 결과를 레이어1에 기록해 보안을 이어받는 확장 네트워크입니다."]],"lesson":{"id":"E08","slug":"sell-vs-withdraw","ep":8,"title":"분명 팔았는데, 왜 은행 계좌에 돈이 안 들어왔을까요?"},"coin":null,"tool":"/rates","cta":false}});
